// TestActionNames asserts every announced file action name is a registered constant.
func TestActionNames(t *testing.T) {

	names := []op.ActionName{
		provider.Backup,
		provider.Copy,
		provider.Discover,
		provider.Exists,
		provider.Find,
		provider.Glob,
		provider.IsDir,
		provider.IsFile,
		provider.Join,
		provider.Link,
		provider.Mkdir,
		provider.Move,
		provider.Name,
		provider.Observe,
		provider.Parent,
		provider.ReadBytes,
		provider.ReadText,
		provider.Remove,
		provider.RemoveAll,
		provider.Resolve,
		provider.Root,
		provider.WalkTree,
		provider.WriteBytes,
		provider.WriteFile,
		provider.WriteText,
	}
	for _, name := range names {
		a := getAction(t, name)
		if got := a.Name(); got != name {
			t.Errorf("Name() = %q, want %q", got, name)
		}
	}
}

