// TestCompensableActions_UndoNil asserts every compensable file action tolerates a nil undo.
func TestCompensableActions_UndoNil(t *testing.T) {

	ctx := newCtx(t)
	activationRecord := op.NewActivationRecord(nil, "", ctx)

	names := []op.ActionName{
		provider.WalkTree,
	}

	for _, name := range names {
		t.Run(string(name), func(t *testing.T) {
			ca := getCompensable(t, name)
			if err := ca.Undo(activationRecord, nil); err != nil {
				t.Errorf("Undo(nil) = %v, want nil", err)
			}
		})
	}
}
